// Read-only ASAR inventory and bounded exact-byte CSS/font extraction. Never executes target JS.
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const parser=require('@babel/parser');
const asar=require('@electron/asar');
const archive=process.argv[2]||'/Applications/ChatGPT.app/Contents/Resources/app.asar';
const destination=__dirname,all=asar.listPackage(archive).map(p=>p.replace(/^\//,'')),set=new Set(all);
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const roots=['side-panel-5865710eeb11.js','aeon-onboarding-ad5bab6d4da0.js','aeon-appearance-picker-60147c2de125.js','room-view-fe0c1087e5e0.js','dot-onboarding-ring-c2e46efd8269.js','dot-onboarding-flight-c16b789b9752.js','orbit-conversation-route-aaed300960dd.js'].map(p=>'webview/assets/'+p);
const records=new Map(),queue=[...roots];
const resolve=(p,ref)=>ref.startsWith('.')?path.posix.normalize(path.posix.join(path.posix.dirname(p),ref)):null;
while(queue.length){const p=queue.shift();if(records.has(p))continue;if(!set.has(p)){records.set(p,{path:p,missing:true});continue;}const b=asar.extractFile(archive,p),s=b.toString();const refs=[];
 const ast=parser.parse(s,{sourceType:'module',createImportExpressions:true,errorRecovery:true});
 for(const declaration of ast.program.body){if((declaration.type==='ImportDeclaration'||declaration.type==='ExportNamedDeclaration'||declaration.type==='ExportAllDeclaration')&&declaration.source){const q=resolve(p,declaration.source.value);if(q)refs.push(q);}}
 const literalDynamic=[...s.matchAll(/\bimport\(["'`]([^"'`]+)["'`]\)/g)].map(m=>resolve(p,m[1])).filter(Boolean);
 const viteHeader=s.match(/^const __vite__mapDeps=[\s\S]*?\n/);const mapped= viteHeader?[...viteHeader[0].matchAll(/["'](\.\/[^"']+)["']/g)].map(m=>resolve(p,m[1])):[];
 const sourceMap=[...s.matchAll(/sourceMappingURL=([^\s]+)/g)].map(m=>({reference:m[1],path:resolve(p,'./'+m[1]),exists:set.has(resolve(p,'./'+m[1]))}));
 const unique=[...new Set(refs)];records.set(p,{path:p,bytes:b.length,sha256:sha(b),staticImportCandidates:unique,literalDynamicImports:[...new Set(literalDynamic)],viteMappedDependencies:[...new Set(mapped)],sourceMaps:sourceMap});queue.push(...unique.filter(q=>q.endsWith('.js')));
}
const selected=all.filter(p=>/webview\/assets\/app-(?:initial|primary|shared)-[^/]+\.css$/.test(p)||/webview\/assets\/OpenAI(?:Sans|Serif)-[^/]+\.woff2$/.test(p)||p==='webview/index.html'||p==='webview/detached-window.html');
const extracted=[];for(const p of selected){const b=asar.extractFile(archive,p);const out=path.join(destination,'original-assets',p);fs.mkdirSync(path.dirname(out),{recursive:true});fs.writeFileSync(out,b);extracted.push({path:p,bytes:b.length,sha256:sha(b),extractedPath:path.relative(destination,out)});}
const cssRecords=extracted.filter(r=>r.path.endsWith('.css')).map(r=>{const s=fs.readFileSync(path.join(destination,r.extractedPath),'utf8');return {path:r.path,fontFaces:[...s.matchAll(/@font-face\s*\{[^}]+\}/g)].map(m=>m[0]),urlDependencies:[...new Set([...s.matchAll(/url\(\s*["']?([^\)"']+)["']?\s*\)/g)].map(m=>m[1]).filter(x=>!x.startsWith('data:')))],sourceMaps:[...s.matchAll(/sourceMappingURL=([^\s*]+)/g)].map(m=>m[1])};});
for(const css of cssRecords){for(const ref of css.urlDependencies){const p=resolve(css.path,ref);if(!p||!set.has(p)||extracted.some(r=>r.path===p))continue;const b=asar.extractFile(archive,p),out=path.join(destination,'original-assets',p);fs.mkdirSync(path.dirname(out),{recursive:true});fs.writeFileSync(out,b);extracted.push({path:p,bytes:b.length,sha256:sha(b),extractedPath:path.relative(destination,out),reason:'Referenced by original global CSS'});}}
const inventory={archive,archiveSha256:'5b5cf52887cfd4de19cb5862155a8ef6cf58830c0a2fc592b72060cfcc3be869',createdAt:new Date().toISOString(),selection:'Seven Dots root modules; recursively inspect static import candidates; extract global CSS, four OpenAI fonts, two HTML entries, and their CSS URL dependencies. No target code executed.',limitations:['Static imports are Babel AST declarations; dynamic imports and Vite preload names remain literal candidates.','Global shared bundles include other features; Dots-only does not imply small dependency closure.','Vite mapped dependencies are preload candidates and optional chunks, not observed runtime loads.','Source map comments do not establish supplied maps.'],totalArchiveFiles:all.length,sourceMapsPresent:all.filter(p=>p.endsWith('.map')),roots,staticClosure:[...records.values()],extracted,cssRecords};fs.writeFileSync(path.join(destination,'original-assets-inventory.json'),JSON.stringify(inventory,null,2)+'\n');console.log(JSON.stringify({files:records.size,closureBytes:[...records.values()].reduce((n,r)=>n+(r.bytes||0),0),extracted:extracted.length,extractedBytes:extracted.reduce((n,r)=>n+r.bytes,0),sourceMaps:inventory.sourceMapsPresent.length,css:cssRecords.map(r=>({path:r.path,urls:r.urlDependencies,fontFaces:r.fontFaces.length}))},null,2));
